import { 
  OneTimeInvestmentInputs, 
  GoalPlannerInputs, 
  MonthlyInvestmentInputs, 
  CalculationResult, 
  SummaryData 
} from '../types';

export const calculateOneTimeInvestment = (inputs: OneTimeInvestmentInputs): { results: CalculationResult[], summary: SummaryData } => {
  const { investmentAmount, duration, durationUnit, profitRate, charityDeduction } = inputs;
  const totalMonths = durationUnit === 'years' ? duration * 12 : duration;
  const monthlyRate = profitRate / 100 / 12;

  const results: CalculationResult[] = [];
  let currentValue = investmentAmount;
  let totalProfit = 0;
  let totalCharity = 0;

  for (let month = 1; month <= totalMonths; month++) {
    const profit = currentValue * monthlyRate;
    const charity = profit * (charityDeduction / 100);
    const netProfit = profit - charity;

    currentValue += netProfit;
    totalProfit += profit;
    totalCharity += charity;

    results.push({
      month,
      profit,
      charity,
      totalProfit: totalProfit,
      accumulatedValue: currentValue
    });
  }

  const summary: SummaryData = {
    totalProfit,
    totalCharity,
    finalValue: currentValue
  };

  return { results, summary };
};

export const calculateGoalPlanner = (inputs: GoalPlannerInputs): { results: CalculationResult[], summary: SummaryData } => {
  const { goalAmount, duration, durationUnit, profitRate } = inputs;
  const totalMonths = durationUnit === 'years' ? duration * 12 : duration;
  const monthlyRate = profitRate / 100 / 12;

  // Calculate required monthly investment using reverse compound interest formula
  const requiredMonthlyInvestment = goalAmount * (monthlyRate / (Math.pow(1 + monthlyRate, totalMonths) - 1));

  const results: CalculationResult[] = [];
  let totalInvested = 0;
  let totalReturn = 0;

  for (let month = 1; month <= totalMonths; month++) {
    totalInvested += requiredMonthlyInvestment;
    totalReturn = totalInvested * Math.pow(1 + monthlyRate, totalMonths - month + 1);

    results.push({
      month,
      monthlyInvestment: requiredMonthlyInvestment,
      totalInvested,
      totalReturn,
      profit: 0,
      charity: 0,
      totalProfit: 0,
      accumulatedValue: totalReturn
    });
  }

  const feasibilityMessage = requiredMonthlyInvestment > goalAmount * 0.1 
    ? "This goal may require significant monthly investment. Consider extending the timeline or adjusting the goal amount."
    : "This goal is achievable with reasonable monthly investment.";

  const summary: SummaryData = {
    totalProfit: totalReturn - totalInvested,
    totalCharity: 0,
    finalValue: totalReturn,
    requiredMonthlyInvestment,
    feasibilityMessage
  };

  return { results, summary };
};

export const calculateMonthlyInvestment = (inputs: MonthlyInvestmentInputs): { results: CalculationResult[], summary: SummaryData } => {
  const { monthlyAmount, duration, profitRate, charityDeduction } = inputs;
  const monthlyRate = profitRate / 100 / 12;

  const results: CalculationResult[] = [];
  let currentValue = 0;
  let totalProfit = 0;
  let totalCharity = 0;

  for (let month = 1; month <= duration; month++) {
    // Add profit on current value
    const profitOnCurrent = currentValue * monthlyRate;
    const charityOnCurrent = profitOnCurrent * (charityDeduction / 100);
    const netProfitOnCurrent = profitOnCurrent - charityOnCurrent;

    // Add monthly investment
    currentValue += netProfitOnCurrent + monthlyAmount;

    // Calculate profit on monthly investment for this month
    const profitOnMonthly = monthlyAmount * monthlyRate * (duration - month + 1);
    const charityOnMonthly = profitOnMonthly * (charityDeduction / 100);
    const netProfitOnMonthly = profitOnMonthly - charityOnMonthly;

    totalProfit += profitOnCurrent + profitOnMonthly;
    totalCharity += charityOnCurrent + charityOnMonthly;

    results.push({
      month,
      monthlyInvestment: monthlyAmount,
      profit: profitOnCurrent + profitOnMonthly,
      charity: charityOnCurrent + charityOnMonthly,
      totalProfit: totalProfit,
      accumulatedValue: currentValue
    });
  }

  const summary: SummaryData = {
    totalProfit,
    totalCharity,
    finalValue: currentValue
  };

  return { results, summary };
};

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(amount);
};

export const formatPercentage = (value: number): string => {
  return `${value.toFixed(2)}%`;
};
